INSERT OR IGNORE INTO "pages" (id, slug, title, content, meta, published) VALUES ('page-terms','terms','Terms of Service','{"title": "Terms of Service", "updated": "November 11, 2026", "intro": "Please read these Terms of Service carefully before using the CareerCode Academy platform. By accessing or using our service, you agree to be bound by these terms.", "sections": [{"title": "1. Acceptance of Terms", "content": "CareerCode Academy is a venture of WID LTD (RC 8824091). By accessing or using CareerCode Academy (the Platform), you agree to be bound by these Terms of Service. If you do not agree, please do not use the Platform. We reserve the right to update these terms at any time, and continued use constitutes acceptance of changes."}, {"title": "2. Account Registration", "content": "You must create an account to access certain features. You are responsible for maintaining the confidentiality of your credentials and for all activities under your account. You must be at least 13 years old to use the Platform."}, {"title": "3. Subscriptions and Billing", "content": "Paid plans are billed in advance on a monthly or annual basis. You may cancel at any time, and access will continue until the end of the billing period. Refunds are handled in accordance with our 30-day money-back guarantee."}, {"title": "4. Intellectual Property", "content": "All course materials, including videos, code samples, exercises, and documentation, are the intellectual property of WID LTD (RC 8824091), which operates CareerCode Academy. You may not redistribute, resell, or publicly share course content without written permission."}, {"title": "5. User Conduct", "content": "You agree to use the Platform responsibly. Prohibited activities include harassment, cheating on assessments, attempting to bypass security measures, and using the Platform for any illegal purpose."}, {"title": "6. Certification", "content": "Certificates are awarded upon successful completion of course requirements. We reserve the right to revoke certificates if fraud or policy violations are discovered. Certificate verification is available to employers."}, {"title": "7. Limitation of Liability", "content": "CareerCode Academy provides educational content as is without warranties of any kind. We are not liable for any damages arising from your use of the Platform, including but not limited to loss of data or missed employment opportunities."}, {"title": "8. Termination", "content": "We may suspend or terminate accounts for violations of these terms. You may delete your account at any time through settings. Upon termination, your access to paid content will cease."}, {"title": "9. Governing Law", "content": "These terms are governed by the laws of the Federal Republic of Nigeria. Any disputes shall be resolved in the courts of Ogun State, Nigeria."}, {"title": "10. Contact", "content": "CareerCode Academy is operated by WID LTD (RC 8824091), Agbara, Ogun State, Nigeria. For questions about these terms, contact contact@widltd.com.ng or +234 816 496 1457, or use our Contact page."}]}','{}',1);
INSERT OR IGNORE INTO "pages" (id, slug, title, content, meta, published) VALUES ('page-privacy','privacy','Privacy Policy','{"title": "Privacy Policy", "updated": "November 11, 2026", "intro": "At CareerCode Academy, a venture of WID LTD (RC 8824091), we take your privacy seriously. This policy describes how we collect, use, and protect your personal information when you use our platform.", "sections": [{"title": "1. Information We Collect", "content": "We collect information you provide directly, including name, email address, payment information, and profile details. We also automatically collect usage data such as pages visited, time spent on courses, and interaction patterns to improve our platform."}, {"title": "2. How We Use Your Information", "content": "Your information is used to provide and improve our educational services, process payments, send updates and marketing communications with consent, personalise your learning experience, and analyse platform usage to enhance our curriculum."}, {"title": "3. Data Sharing and Disclosure", "content": "We do not sell your personal information. We may share data with trusted third-party service providers who help us operate the platform, including payment processors, cloud hosting and analytics. These providers are contractually bound to protect your data."}, {"title": "4. Data Security", "content": "We implement industry-standard security measures including encryption at rest and in transit, regular security audits, and strict access controls. However, no method of transmission over the Internet is completely secure."}, {"title": "5. Your Rights", "content": "You have the right to access, correct, or delete your personal data. You can manage your data through account settings or by contacting us. You may opt out of marketing communications at any time."}, {"title": "6. Cookies", "content": "We use cookies and similar technologies to enhance your experience, analyse usage, and deliver relevant content. You can manage cookie preferences through your browser settings. See our Cookie Policy for more details."}, {"title": "7. Data Retention", "content": "We retain your account information for as long as your account is active. Course progress and certificates are retained to maintain your learning history. Deleted account data is purged within 90 days."}, {"title": "8. Children Privacy", "content": "The Platform is not intended for children under 13. We do not knowingly collect data from children. If you believe a child has provided us with personal data, please contact us immediately."}, {"title": "9. International Transfers", "content": "Your data may be transferred to and processed in countries other than your own. We ensure appropriate safeguards are in place through standard contractual clauses and data processing agreements."}, {"title": "10. Changes to This Policy", "content": "We may update this Privacy Policy periodically. Material changes will be notified via email or platform notice. Continued use after changes constitutes acceptance of the updated policy."}, {"title": "11. Contact", "content": "The data controller is WID LTD (RC 8824091), Agbara, Ogun State, Nigeria. Contact contact@widltd.com.ng or +234 816 496 1457 for privacy requests."}]}','{}',1);
INSERT OR IGNORE INTO "pages" (id, slug, title, content, meta, published) VALUES ('page-cookies','cookies','Cookie Policy','{"title": "Cookie Policy", "updated": "November 11, 2026", "intro": "This Cookie Policy explains how WID LTD (RC 8824091), which operates CareerCode Academy, uses cookies and similar tracking technologies to enhance your experience on our platform.", "sections": [{"title": "1. What Are Cookies", "content": "Cookies are small text files stored on your device by your web browser. They help websites remember your preferences, login status, and other information to provide a better browsing experience."}, {"title": "2. How We Use Cookies", "content": "We use cookies to authenticate your account, remember your preferences including theme and language settings, analyse platform usage to improve our services, deliver relevant content and marketing, and maintain session state during course playback."}, {"title": "3. Types of Cookies We Use", "content": "Essential cookies are required for the platform to function, including login and security. Analytics cookies help us understand how you interact with our platform. Preference cookies remember your settings. Marketing cookies track your engagement with our campaigns."}, {"title": "4. Third-Party Cookies", "content": "Some third-party services we use may place cookies on your device. These include payment processors, analytics providers, and video hosting platforms. We do not control these cookies and recommend reviewing their privacy policies."}, {"title": "5. Managing Cookies", "content": "You can control and delete cookies through your browser settings. Most browsers allow you to block or delete cookies. Note that disabling essential cookies may affect platform functionality, including login and course progress tracking."}, {"title": "6. Cookie Retention", "content": "Session cookies expire when you close your browser. Persistent cookies remain on your device for up to 12 months or until manually deleted. You can clear cookies at any time through your browser settings."}, {"title": "7. Do Not Track", "content": "Our platform does not respond to Do Not Track signals at this time. We follow industry standards and provide you with control over cookies through browser settings."}, {"title": "8. Updates to This Policy", "content": "We may update this Cookie Policy from time to time. Changes will be posted on this page with an updated effective date. We encourage you to review this policy periodically."}], "cookies": [{"name": "session_id", "purpose": "Authentication and session management", "duration": "Session", "type": "Essential"}, {"name": "auth_token", "purpose": "Remember login status across pages", "duration": "7 days", "type": "Essential"}, {"name": "theme_pref", "purpose": "Remember dark or light mode preference", "duration": "1 year", "type": "Preference"}, {"name": "course_progress", "purpose": "Track course completion progress", "duration": "1 year", "type": "Preference"}, {"name": "ga_analytics", "purpose": "Analyse platform usage patterns", "duration": "2 years", "type": "Analytics"}, {"name": "marketing_ref", "purpose": "Track referral and campaign sources", "duration": "90 days", "type": "Marketing"}]}','{}',1);
